{"concept":"A forbidding, high-tech Latverian fortress of absolute iron, smoldering reactor cores, and dark sorcery.","fingerprint":"Cinzel, Doom palette, iron brackets, radioactive sparks","needsHud":false,"hudReason":"","id":"bcaa9e9706ee","name":"Doom's Latverian Lair","dark":true,"bg":"#0a0a0c","surface":"#161922","surface2":"#242a38","fg":"#dce4ef","ink":"#f5f6f8","accent":"#00ff66","remapSurfaces":true,"customCss":":root{--m-bg:#0a0a0c;--m-surface:#161922;--m-surface2:#242a38;--m-fg:#dce4ef;--m-ink:#f5f6f8;--m-accent:#00ff66;--m-secondary:#ff2a2a;--m-tertiary:#d4af37;--m-deep:#8b0000;--body-font:'Roboto',sans-serif;--heading-font:'Cinzel Decorative',serif;}
@keyframes doomDrift{0%{background-position:0 0,0 0,0 0}100%{background-position:180px 360px,-260px 520px,340px 680px}}
@keyframes doomTwinkle{0%,100%{opacity:.45}50%{opacity:.98}}
@keyframes doomRift{0%,100%{opacity:.25;transform:scale(1)}50%{opacity:.75;transform:scale(1.05)}}
@keyframes doomHeaderGlow{0%,100%{box-shadow:0 4px 18px rgba(255,42,42,.4),inset 0 -1px 0 rgba(0,255,102,.5)}50%{box-shadow:0 6px 28px rgba(255,42,42,.75),inset 0 -1px 0 #00ff66}}
@keyframes doomSearchPulse{0%,100%{box-shadow:0 0 10px rgba(0,255,102,.4),inset 0 0 8px rgba(0,255,102,.2)}50%{box-shadow:0 0 22px rgba(0,255,102,.85),0 0 34px rgba(255,42,42,.45),inset 0 0 12px rgba(0,255,102,.35)}}
@keyframes doomShimmer{0%,100%{text-shadow:0 0 8px #00ff66,0 0 18px #ff2a2a,0 2px 0 #000}50%{text-shadow:0 0 12px #ff2a2a,0 0 28px #d4af37,0 2px 0 #000}}
@keyframes doomBtnPulse{0%,100%{box-shadow:0 0 10px rgba(0,255,102,.5),0 4px 12px rgba(255,42,42,.4)}50%{box-shadow:0 0 20px rgba(0,255,102,.9),0 6px 20px rgba(255,42,42,.6)}}html, body{background-color:var(--m-bg)!important;color:var(--m-fg)!important;font-family:var(--body-font)!important;background-image:radial-gradient(ellipse 80% 50% at 10% 10%,rgba(0,255,102,.15),transparent),radial-gradient(ellipse 60% 40% at 90% 20%,rgba(255,42,42,.12),transparent),radial-gradient(ellipse 70% 60% at 50% 80%,rgba(212,175,55,.1),transparent),repeating-conic-gradient(from 0deg at 50% 50%,rgba(255,42,42,.04) 0deg 12deg,transparent 12deg 24deg),radial-gradient(circle 2px at 0 0,rgba(255,255,255,.03) 1px,transparent 1px),radial-gradient(circle 1px at 3px 3px,rgba(0,255,102,.02) 1px,transparent 1px);background-size:600px 600px,500px 500px,700px 700px,400px 400px,24px 24px,12px 12px;background-repeat:no-repeat,no-repeat,no-repeat,repeat,repeat,repeat;background-attachment:fixed!fixed!important;}body::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:1;mix-blend-mode:screen;background-image:radial-gradient(circle at 10px 10px,#00ff66 0,#00ff66 1.6px,rgba(0,255,102,.65) 3.5px,transparent 5px),radial-gradient(circle at 12px 8px,#ff2a2a 0,#ff2a2a 1.4px,rgba(255,42,42,.6) 3px,transparent 4.5px),radial-gradient(circle at 8px 12px,#d4af37 0,#d4af37 1.2px,rgba(212,175,55,.55) 2.8px,transparent 4px);background-size:180px 180px,260px 260px,340px 340px;background-repeat:repeat,repeat,repeat;animation:doomDrift 40s linear infinite,doomTwinkle 3.8s ease-in-out infinite;}body::after{content:"";position:fixed;inset:0;pointer-events:none;z-index:1;mix-blend-mode:screen;background-image:repeating-conic-gradient(from 0deg at 50% 50%,rgba(255,42,42,.4) 0deg 6deg,transparent 6deg 12deg),radial-gradient(ellipse 120% 120% at 50% 50%,rgba(0,255,102,.8) 0%,transparent 70%);-webkit-mask-image:radial-gradient(circle at 50% 50%,black 0%,transparent 80%);mask-image:radial-gradient(circle at 50% 50%,black 0%,transparent 80%);animation:doomRift 7s ease-in-out infinite;}[data-mydes="header"], header, [data-mydes="bottom-bar"]{background-image:radial-gradient(circle at 10px 6px,#ff2a2a 0,#ff2a2a 1.6px,rgba(255,42,42,.65) 3.5px,transparent 5px),radial-gradient(circle at 30px 6px,#8b0000 0,#8b0000 1.4px,rgba(139,0,0,.6) 3px,transparent 4.5px),linear-gradient(90deg,transparent,#ff2a2a,#d4af37,#ff2a2a,transparent),radial-gradient(ellipse 100% 100% at 50% 0%,rgba(0,255,102,.25),transparent),linear-gradient(180deg,var(--m-surface),var(--m-surface2));background-size:40px 12px,40px 12px,100% 1.5px,100% 100%,100% 100%;background-repeat:repeat-x,repeat-x,no-repeat,no-repeat,no-repeat;background-position:0 100%,0 100%,0 calc(100% - 4px),0 0,0 0;box-shadow:0 4px 18px rgba(255,42,42,.4),inset 0 -1px 0 rgba(0,255,102,.5);animation:doomHeaderGlow 4s ease-in-out infinite;}
