[data-mydes="search"]:focus-within,yt-searchbox:focus-within{animation:doomSearchPulse 2s ease-in-out infinite;}
[data-mydes="search"] input,[data-mydes="search"] input::placeholder{color:var(--m-fg)!important;font-family:var(--body-font)!important;}
