))!important;color:var(--m-bg)!important;border-color:transparent!important;box-shadow:0 0 14px rgba(0,255,102,.9),0 0 24px rgba(255,42,42,.6)!important;}[data-mydes="card"]{background-image:radial-gradient(circle at 0 0,#d4af37 0,#d4af37 3px,rgba(212,175,55,.4) 4px,rgba(212,175,55,.4) 8px,transparent 9px),radial-gradient(circle at 100% 0,#d4af37 0,#d4af37 3px,rgba(212,175,55,.4) 4px,rgba(212,175,55,.4) 8px,transparent 9px),radial-gradient(circle at 0 100%,#ff2a2a 0,#ff2a2a 3px,rgba(255,42,42,.4) 4px,rgba(255,42,42,.4) 8px,transparent 9px),radial-gradient(circle at 100% 100%,#ff2a2a 0,#ff2a2a 3px,rgba(255,42,42,.4) 4px,rgba(255,42,42,.4) 8px,transparent 9px),linear-gradient(90deg,transparent,var(--m-accent),transparent),repeating-linear-gradient(45deg,rgba(255,255,255,.02) 0,rgba(255,255,255,.02) 1px,transparent 1px,transparent 3px),linear-gradient(135deg,#0f0f12,#1a1d26 55%,#0a0a0c)!important;background-size:16px 16px,16px 16px,16px 16px,16px 16px,100% 2px,100% 100%,100% 100%!important;background-position:0 0,100% 0,0 100%,100% 100%,0 0,0 0,0 0!important;background-repeat:no-repeat,no-repeat,no-repeat,no-repeat,no-repeat,repeat,no-repeat!important;border-radius:12px!important;border:1px solid var(--m-accent)!important;box-shadow:0 0 12px rgba(0,255,102,.35),0 4px 14px rgba(0,0,0,.7),inset 0 0 12px rgba(0,255,102,.15)!important;overflow:hidden;}[data-mydes="card"]:nth-child(3n+2){border:1.5px solid var(--m-secondary)!important;box-shadow:0 0 18px rgba(255,42,42,.55),0 6px 16px rgba(0,0,0,.75),inset 0 0 16px rgba(255,42,42,.2)!important;}[data-mydes="card"]:nth-child(3n){border:1.5px solid var(--m-tertiary)!important;box-shadow:0 0 18px rgba(212,175,55,.55),0 6px 16px rgba(0,0,0,.75),inset 0 0 16px rgba(212,175,55,.2)!important;}[data-mydes="card"] img{border-radius:10px!important;filter:saturate(1.15) contrast(1.1)!important;box-shadow:0 0 0 1px rgba(0,255,102,.6),0 4px 12px rgba(255,42,42,.35)!important;}
[data-mydes="heading"],[data-mydes="title"]{font-family:var(--heading-font)!important;text-transform:uppercase!important;letter-spacing:.12em!important;color:var(--m-ink)!important;text-shadow:0 0 8px rgba(0,255,102,.65),0 0 18px rgba(255,42,42,.45),0 2px 0 #000!important;animation:doomShimmer 4s ease-in-out infinite;}
[data-mydes="heading"]::before{content:"⚡ ";color:var(--m-accent)!important;text-shadow:0 0 8px var(--m-accent);}[data-mydes="btn"]:not(:has(svg, img)):not([aria-label]){background-image:linear-gradient(135deg,var(--m-accent),var(--m-secondary),var(--m-tertiary))!important;border:1px solid var(--m-accent)!important;border-radius:6px!important;padding:10px 20px!important;color:var(--m-bg)!important;font-weight:700!important;text-transform:uppercase!important;letter-spacing:.08em!important;box-shadow:0 0 10px rgba(0,255,102,.5),0 4px 12px rgba(255,42,42,.4)!important;animation:doomBtnPulse 2.8s ease-in-out infinite;}

/* review */
[data-mydes="heading"],[data-mydes="title"],header span,header a{color:var(--m-ink)!important;text-shadow:0 0 10px #00ff66,0 0 20px #000000,0 2px 4px #000!important;} [data-mydes="bottom-bar"] a, [data-mydes="bottom-bar"] span {color:var(--m-fg)!important;text-shadow:0 0 6px #000!important;}","backdropHtml":"","hudHtml":"","customJs":""}

